<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
use DI\ContainerBuilder;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepName;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\OidcUrlBuilder;

/**
 * Unit tests for {@see OidcUrlBuilder}.
 */
#[AllowMockObjectsWithoutExpectations]
final class OidcUrlBuilderUnitTest extends TestCase
{
    private array $serverBackup = [];

    #[Override]
    protected function setUp(): void
    {
        $this->serverBackup = $_SERVER;
        $_SERVER['HTTPS'] = 'on';
        $_SERVER['HTTP_HOST'] = 'example.com';
        $_SERVER['SCRIPT_NAME'] = '/index.php';
    }

    #[Override]
    protected function tearDown(): void
    {
        $_SERVER = $this->serverBackup;
    }

    /**
     * Verifies authorizeUrl builds expected base parameters.
     */
    public function testAuthorizeUrl(): void
    {
        $builder = $this->createBuilder();

        $request = new AuthenticationRequest(
            client: new ClientData('client-123', ['code'], true),
            scope: 'openid profile',
            redirect: 'https://client.example/callback',
            responseType: 'code',
            audiences: ['api', 'client-123']
        );

        $url = $builder->authorizeUrl($request, 'tenant1', 'state-xyz', 'nonce-abc');
        $this->assertStringContainsString('https://example.com/oauth/openid/tenant1/authorize?', $url);

        $query = $this->parseQuery($url);
        $this->assertSame('client-123', $query['client_id']);
        $this->assertSame('openid profile', $query['scope']);
        $this->assertSame('state-xyz', $query['state']);
        $this->assertSame('nonce-abc', $query['nonce']);
        $this->assertSame('api,client-123', $query['audience']);
        $this->assertSame('https://client.example/callback', $query['redirect_uri']);
        $this->assertSame('code', $query['response_type']);
    }

    /**
     * Verifies registerUserUrl appends step and suffix.
     */
    public function testRegisterUserUrlWithSuffix(): void
    {
        $builder = $this->createBuilder();

        $request = new AuthenticationRequest(
            client: new ClientData('client-123', ['code'], true),
            scope: 'openid',
            redirect: 'https://client.example/callback',
            responseType: 'code',
            audiences: ['client-123']
        );

        $url = $builder->registerUserUrl($request, 'tenant1', 'state-xyz', 'nonce-abc', '&_use_code=');

        $query = $this->parseQuery($url);
        $this->assertSame(StepName::REGISTER_USER->value, $query['step']);
        $this->assertSame('true', $query['verify_send']);
        $this->assertStringEndsWith('_use_code=', $url);
    }

    /**
     * Verifies recoverPassUrl appends step and suffix.
     */
    public function testRecoverPassUrlWithSuffix(): void
    {
        $builder = $this->createBuilder();

        $request = new AuthenticationRequest(
            client: new ClientData('client-123', ['code'], true),
            scope: 'openid',
            redirect: 'https://client.example/callback',
            responseType: 'code',
            audiences: ['client-123']
        );

        $url = $builder->recoverPassUrl($request, 'tenant1', 'state-xyz', 'nonce-abc', '&_use_code=');

        $query = $this->parseQuery($url);
        $this->assertSame(StepName::RECOVER_PASS->value, $query['step']);
        $this->assertSame('true', $query['recover_send']);
        $this->assertStringEndsWith('_use_code=', $url);
    }

    private function createBuilder(): OidcUrlBuilder
    {
        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $context = new Context($builder, $config);
        return new OidcUrlBuilder($context);
    }

    private function parseQuery(string $url): array
    {
        $parts = parse_url($url);
        $query = [];
        parse_str($parts['query'] ?? '', $query);
        return $query;
    }
}
